import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import {
  SEARCH_DROPDOWN_PORTAL,
  catalogColumnName,
  catalogLookupColumns,
  catalogLookupHeader,
} from '../../search/searchDropdownDefaults';
import { apiClient, unwrap, type BffResponse } from '../api';
import {
  ROAD_ROUTE_LOOKUP_CONFIG,
  type MasterLookupItem,
} from '../attendance/lookups';

export const ORG_FORM_LOOKUP_PORTAL = {
  ...SEARCH_DROPDOWN_PORTAL,
  dropdownMatch: 'row' as const,
  dropdownMinWidth: '32rem',
};

type OrgUnitRow = { code?: string; name?: string; kind?: string };
type PartnerRow = { code?: string; name?: string };

function pagedItems<T>(raw: T[] | { items?: T[] } | null | undefined): T[] {
  return Array.isArray(raw) ? raw : raw?.items ?? [];
}

function toLookup(code: string, name?: string): MasterLookupItem {
  const c = code.trim();
  return { value: c, label: name?.trim() ? `${c} — ${name.trim()}` : c };
}

function matchLookup(item: MasterLookupItem, search?: string): boolean {
  const q = (search ?? '').trim().toLowerCase();
  if (!q) return true;
  return item.value.toLowerCase().includes(q) || item.label.toLowerCase().includes(q);
}

async function searchOrgUnits(opts: {
  search?: string;
  kind?: string;
  parentCode?: string;
}): Promise<OrgUnitRow[]> {
  const qs = new URLSearchParams();
  qs.set('page', '1');
  qs.set('pageSize', '100');
  if (opts.search) qs.set('search', opts.search);
  if (opts.kind) qs.set('kind', opts.kind);
  if (opts.parentCode) qs.set('parentCode', opts.parentCode);
  const res = await apiClient.get<BffResponse<OrgUnitRow[] | { items?: OrgUnitRow[] }>>(
    `/integration/org-units?${qs}`,
  );
  return pagedItems(unwrap(res));
}

async function searchPartners(opts?: {
  search?: string;
  zoneOrgCode?: string;
  vpOrgCode?: string;
}): Promise<PartnerRow[]> {
  const qs = new URLSearchParams();
  qs.set('page', '1');
  qs.set('pageSize', '100');
  if (opts?.search) qs.set('search', opts.search);
  if (opts?.zoneOrgCode) qs.set('zoneOrgCode', opts.zoneOrgCode);
  if (opts?.vpOrgCode) qs.set('vpOrgCode', opts.vpOrgCode);
  const res = await apiClient.get<BffResponse<PartnerRow[] | { items?: PartnerRow[] }>>(
    `/integration/partner-units/search?${qs}`,
  );
  return pagedItems(unwrap(res));
}

async function findOrgByCode(code: string): Promise<MasterLookupItem> {
  const needle = code.trim();
  if (!needle) return { value: '', label: '' };
  try {
    const rows = await searchOrgUnits({ search: needle });
    const hit = rows.find((r) => (r.code ?? '').toUpperCase() === needle.toUpperCase());
    if (hit?.code) return toLookup(hit.code, hit.name);
  } catch {
    /* detail fallback */
  }
  return { value: needle, label: needle };
}

async function findPartnerByCode(code: string): Promise<MasterLookupItem> {
  const needle = code.trim();
  if (!needle) return { value: '', label: '' };
  try {
    const rows = await searchPartners({ search: needle });
    const hit = rows.find((r) => (r.code ?? '').toUpperCase() === needle.toUpperCase());
    if (hit?.code) return toLookup(hit.code, hit.name);
  } catch {
    /* detail fallback */
  }
  return { value: needle, label: needle };
}

function lookupConfig(
  search: (q?: string) => Promise<MasterLookupItem[]>,
  detail: (id: string) => Promise<MasterLookupItem>,
): SearchInputConfig<MasterLookupItem> {
  return {
    pageSize: 50,
    api: {
      getItemKey: (i) => i.value,
      search: async ({ search: q }) => {
        const items = await search(q);
        return { items, page: 1, totalPages: 1 };
      },
      getDetail: detail,
    },
    display: {
      getPrimaryDisplay: (i) => i.value,
      getSecondaryDisplay: (i) => catalogColumnName(i.value, i.label),
      getSingleDisplay: (i) => i.label,
    },
    ...ORG_FORM_LOOKUP_PORTAL,
    columns: catalogLookupColumns(),
    header: catalogLookupHeader(),
  };
}

export function createVpOrgLookupConfig(options?: {
  parentCode?: string;
}): SearchInputConfig<MasterLookupItem> {
  return lookupConfig(
    async (search) => {
      const rows = await searchOrgUnits({
        search,
        kind: 'VP',
        parentCode: options?.parentCode || undefined,
      });
      return rows
        .filter((r) => r.code && (r.kind ?? '').toUpperCase() === 'VP')
        .map((r) => toLookup(String(r.code), r.name));
    },
    async (id) => findOrgByCode(id),
  );
}

const SU_GROUP = 'SU';

async function loadAssigneeUnits(options?: {
  zoneOrgCode?: string;
  vpOrgCode?: string;
}): Promise<MasterLookupItem[]> {
  const vp = (options?.vpOrgCode ?? '').trim().toUpperCase();
  const zone = (options?.zoneOrgCode ?? '').trim().toUpperCase();
  const map = new Map<string, MasterLookupItem>();
  const put = (code: string, name?: string, kind?: string) => {
    const key = code.trim().toUpperCase();
    const k = (kind ?? '').toUpperCase();
    if (!key || key === SU_GROUP || k === 'VP' || k === 'ROOM' || map.has(key)) return;
    if (vp && key === vp) return;
    map.set(key, toLookup(code, name));
  };

  const [su, partners, children] = await Promise.all([
    vp ? Promise.resolve([] as OrgUnitRow[]) : searchOrgUnits({ kind: 'SU' }),
    searchPartners({ zoneOrgCode: zone || undefined, vpOrgCode: vp || undefined }),
    vp ? searchOrgUnits({ parentCode: vp }) : Promise.resolve([] as OrgUnitRow[]),
  ]);
  for (const x of su) {
    if (x.code) put(x.code, x.name, x.kind || 'SU');
  }
  for (const x of children) {
    if (x.code) put(x.code, x.name, x.kind);
  }
  for (const x of partners) {
    if (x.code) put(x.code, x.name, 'PARTNER');
  }
  return [...map.values()];
}

export function createAssigneeUnitLookupConfig(options?: {
  zoneOrgCode?: string;
  vpOrgCode?: string;
}): SearchInputConfig<MasterLookupItem> {
  const vp = (options?.vpOrgCode ?? '').trim().toUpperCase();
  const zone = (options?.zoneOrgCode ?? '').trim().toUpperCase();
  return lookupConfig(
    async (search) => {
      const items = await loadAssigneeUnits({
        zoneOrgCode: zone || undefined,
        vpOrgCode: vp || undefined,
      });
      return items.filter((i) => matchLookup(i, search));
    },
    async (id) => {
      const partner = await findPartnerByCode(id);
      if (partner.label !== partner.value) return partner;
      const org = await findOrgByCode(id);
      if ((org.value ?? '').toUpperCase() === vp) return partner;
      return org;
    },
  );
}

export const ZONE_ORG_FORM_CONFIG: SearchInputConfig<MasterLookupItem> = lookupConfig(
  async (search) => {
    const rows = await searchOrgUnits({ search, kind: 'REG' });
    return rows
      .filter((r) => r.code && (r.code ?? '').toUpperCase() !== 'REG')
      .map((r) => toLookup(String(r.code), r.name));
  },
  async (id) => findOrgByCode(id),
);

export const ROAD_ROUTE_FORM_CONFIG: SearchInputConfig<MasterLookupItem> = {
  ...ROAD_ROUTE_LOOKUP_CONFIG,
  ...ORG_FORM_LOOKUP_PORTAL,
  display: {
    getPrimaryDisplay: (i) => i.value,
    getSecondaryDisplay: (i) => catalogColumnName(i.value, i.label),
    getSingleDisplay: (i) => i.label,
  },
};

export function pickOrgCodeName(item: {
  value?: string;
  label?: string;
  code?: string;
  name?: string;
}): { code: string; name: string } {
  const code = (item.code || item.value || '').trim();
  const raw = (item.name || item.label || '').trim();
  return { code, name: catalogColumnName(code, raw) || code };
}
