import React, { useMemo } from 'react';
import { SearchInput } from '@linm-soft-org/linm-web-common-components';
import {
  ROAD_ROUTE_FORM_CONFIG,
  ZONE_ORG_FORM_CONFIG,
  createAssigneeUnitLookupConfig,
  createVpOrgLookupConfig,
  pickOrgCodeName,
} from '../services/org/orgFormLookups';
import type { RmmsOrgFormValue } from './rmmsOrgForm';

export type RmmsOrgFormFieldsProps = {
  testIdPrefix: string;
  value: RmmsOrgFormValue;
  onChange: (next: RmmsOrgFormValue) => void;
  disabled?: boolean;
  routeRequired?: boolean;
  routeError?: string;
};

/**
 * Form cascade Khu → VP → Đơn vị → Tuyến.
 * Đổi Khu → clear VP+ĐV+Tuyến. Đổi VP → clear ĐV. Cục không ô. km_skip.
 */
export const RmmsOrgFormFields: React.FC<RmmsOrgFormFieldsProps> = ({
  testIdPrefix,
  value,
  onChange,
  disabled,
  routeRequired = true,
  routeError,
}) => {
  const vpConfig = useMemo(
    () => createVpOrgLookupConfig({ parentCode: value.zoneOrgCode || undefined }),
    [value.zoneOrgCode],
  );
  const unitConfig = useMemo(
    () =>
      createAssigneeUnitLookupConfig({
        zoneOrgCode: value.zoneOrgCode || undefined,
        vpOrgCode: value.vpOrgCode || undefined,
      }),
    [value.zoneOrgCode, value.vpOrgCode],
  );

  return (
    <>
      <div data-testid={`${testIdPrefix}-field-zoneOrgCode`}>
        <SearchInput
          label="Khu"
          config={ZONE_ORG_FORM_CONFIG}
          value={value.zoneOrgCode}
          primaryDisplay={value.zoneOrgCode || undefined}
          secondaryDisplay={value.zoneOrgName || undefined}
          placeholder="Mã…"
          disabled={disabled}
          onChange={(item) => {
            const { code, name } = pickOrgCodeName(item);
            onChange({
              ...value,
              zoneOrgCode: code,
              zoneOrgName: name,
              vpOrgCode: '',
              vpOrgName: '',
              assigneeCode: '',
              assigneeName: '',
              routeCode: '',
              routeName: '',
            });
          }}
          onClear={() =>
            onChange({
              ...value,
              zoneOrgCode: '',
              zoneOrgName: '',
              vpOrgCode: '',
              vpOrgName: '',
              assigneeCode: '',
              assigneeName: '',
              routeCode: '',
              routeName: '',
            })
          }
          data-testid={`${testIdPrefix}-zoneOrgCode`}
        />
      </div>
      <div data-testid={`${testIdPrefix}-field-vpOrgCode`}>
        <SearchInput
          label="Văn phòng"
          config={vpConfig}
          value={value.vpOrgCode}
          primaryDisplay={value.vpOrgCode || undefined}
          secondaryDisplay={value.vpOrgName || undefined}
          placeholder="Mã…"
          disabled={disabled}
          onChange={(item) => {
            const { code, name } = pickOrgCodeName(item);
            onChange({
              ...value,
              vpOrgCode: code,
              vpOrgName: name,
              assigneeCode: '',
              assigneeName: '',
            });
          }}
          onClear={() =>
            onChange({
              ...value,
              vpOrgCode: '',
              vpOrgName: '',
              assigneeCode: '',
              assigneeName: '',
            })
          }
          data-testid={`${testIdPrefix}-vpOrgCode`}
        />
      </div>
      <div data-testid={`${testIdPrefix}-field-assigneeCode`}>
        <SearchInput
          label="Đơn vị"
          config={unitConfig}
          value={value.assigneeCode}
          primaryDisplay={value.assigneeCode || undefined}
          secondaryDisplay={value.assigneeName || undefined}
          placeholder="Mã…"
          disabled={disabled}
          onChange={(item) => {
            const { code, name } = pickOrgCodeName(item);
            onChange({ ...value, assigneeCode: code, assigneeName: name });
          }}
          onClear={() => onChange({ ...value, assigneeCode: '', assigneeName: '' })}
          data-testid={`${testIdPrefix}-assigneeCode`}
        />
      </div>
      <div data-testid={`${testIdPrefix}-field-routeCode`}>
        <SearchInput
          label="Tuyến"
          required={routeRequired}
          config={ROAD_ROUTE_FORM_CONFIG}
          value={value.routeCode}
          primaryDisplay={value.routeCode || undefined}
          secondaryDisplay={value.routeName || undefined}
          placeholder="Mã…"
          disabled={disabled}
          onChange={(item) => {
            const { code, name } = pickOrgCodeName(item);
            onChange({ ...value, routeCode: code, routeName: name });
          }}
          onClear={() => onChange({ ...value, routeCode: '', routeName: '' })}
          error={routeError}
          data-testid={`${testIdPrefix}-routeCode`}
        />
      </div>
    </>
  );
};
