export type RmmsOrgFormValue = {
  zoneOrgCode: string;
  zoneOrgName: string;
  vpOrgCode: string;
  vpOrgName: string;
  assigneeCode: string;
  assigneeName: string;
  routeCode: string;
  routeName: string;
};

export const EMPTY_RMMS_ORG_FORM: RmmsOrgFormValue = {
  zoneOrgCode: '',
  zoneOrgName: '',
  vpOrgCode: '',
  vpOrgName: '',
  assigneeCode: '',
  assigneeName: '',
  routeCode: '',
  routeName: '',
};

/** POST/PUT body — assigneeOrgName = Đơn vị (≠ người xử lý). */
export function orgPersistPayload(org: RmmsOrgFormValue): {
  zoneOrgCode?: string;
  zoneOrgName?: string;
  vpOrgCode?: string;
  vpOrgName?: string;
  assigneeCode?: string;
  assigneeOrgName?: string;
  routeCode?: string;
} {
  const n = (v: string) => v.trim() || undefined;
  return {
    zoneOrgCode: n(org.zoneOrgCode),
    zoneOrgName: n(org.zoneOrgName),
    vpOrgCode: n(org.vpOrgCode),
    vpOrgName: n(org.vpOrgName),
    assigneeCode: n(org.assigneeCode),
    assigneeOrgName: n(org.assigneeName),
    routeCode: n(org.routeCode),
  };
}

export function orgFromDto(dto: {
  zoneOrgCode?: string | null;
  zoneOrgName?: string | null;
  vpOrgCode?: string | null;
  vpOrgName?: string | null;
  assigneeCode?: string | null;
  assigneeOrgName?: string | null;
  routeCode?: string | null;
  routeName?: string | null;
  route?: string | null;
}): RmmsOrgFormValue {
  const routeCode = (dto.routeCode || dto.route || dto.routeName || '').trim();
  return {
    zoneOrgCode: dto.zoneOrgCode ?? '',
    zoneOrgName: dto.zoneOrgName ?? '',
    vpOrgCode: dto.vpOrgCode ?? '',
    vpOrgName: dto.vpOrgName ?? '',
    assigneeCode: dto.assigneeCode ?? '',
    assigneeName: dto.assigneeOrgName ?? '',
    routeCode,
    routeName: dto.routeName ?? '',
  };
}
